"""v3.7.1: what the models are told about their environment, built from the
live config every turn, plus a lint and a safe migration for system prompts.

- environment_block(ent, role): the ENVIRONMENT section added to the persona,
  reasoning and coding prompts at runtime: the entity and memory profile, the
  memory store and whether it is connected, that recall is automatic before
  each reply and saving happens after it, the built-in memory_search tool when
  it is offered, the exact MCP tool names the model may call (and that no
  other tools exist), the active roles, the channel and its output rules.
  Prompts never go stale when tools or settings change.
- lint_prompts(prompts, available): warnings for prompts that name a tool
  that is not available ("persona mentions quill_mem, which is not an
  available tool").
- migrate_prompt_text / migrate_prompts_file: rewrite the sentences that
  tell a model to call a tool that does not exist, keep everything else
  word for word, and back the file up first.
"""
import contextlib
import contextvars
import os
import re
import shutil
import time

CHANNELS = {
    "terminal": "terminal chat",
    "voice": "voice call",
    "telegram": "Telegram",
    "telegram_voice": "Telegram voice message",
    "endpoint": "the OpenAI-compatible endpoint (a chat app or another program)",
    "scheduler": "a scheduled run (the heartbeat or a scheduler job); nobody is reading live, so the reply goes "
                 "wherever the job routes it",
}
VOICE_CHANNELS = {"voice", "telegram_voice"}
ENV_ROLES = ("persona", "reasoning", "coding")

_channel = contextvars.ContextVar("nimlab_channel", default=None)


def current_channel():
    return _channel.get()


@contextlib.contextmanager
def channel(name):
    """with channel("voice"): ... -- the front end that is talking to the user."""
    tok = _channel.set(name)
    try:
        yield
    finally:
        _channel.reset(tok)


def output_rules(ch):
    if ch in VOICE_CHANNELS:
        return ("Your reply is spoken aloud by the text-to-speech role. Write short spoken sentences only: no "
                "lists, bullets, headings, markdown, tables, code blocks, links, emoji, brackets or tool markup. "
                "These voice rules win over any style guidance elsewhere (soul.md's preference for lists and "
                "artifacts applies to text channels only). Say a list as a sentence.")
    if ch == "telegram":
        return ("Plain text for a phone screen: short paragraphs; simple lists are fine; no tables, HTML or tool "
                "markup.")
    if ch == "endpoint":
        return "Markdown is fine. Never write tool-call markup or template tokens in the reply."
    return "Plain text for a terminal: short paragraphs and simple lists; no tool-call markup or template tokens."


def environment_block(ent, role="persona", tool_names=None):
    """The ENVIRONMENT section for one role, from the live config.

    tool_names: the tools this model can call right now (from the tool box);
    None works them out from the policy."""
    if role not in ENV_ROLES:
        return ""
    lines = ["=== ENVIRONMENT (generated by the testbed from the live settings; it overrides older instructions "
             "about tools or memory) ==="]
    prof = _safe(lambda: ent.memory_profile(), "TESTBED")
    speaks = role == "persona" or _safe(lambda: bool(ent.soul_for(role)), False)
    if speaks:
        name = _safe(lambda: ent.agent_name(), "") or "the testbed entity"
        lines.append(f"- You are {name}. Memory profile: {prof}.")
    else:
        lines.append(f"- You are a specialist step; your output goes to the persona, which answers the user. "
                     f"Memory profile: {prof}.")
    m = getattr(ent, "memory", None)
    if m is None or (getattr(m, "settings", {}) or {}).get("backend") == "off":
        lines.append("- Long-term memory is off: you remember only this conversation. Do not claim to remember "
                     "earlier sessions.")
    else:
        where = _safe(lambda: m.where(), "")
        state = f"OFFLINE right now ({str(m.offline)[:100]})" if m.offline else "connected"
        lines.append(f"- Long-term memory: {m.backend_name}{(' ' + where) if where else ''}, {state}. It is "
                     "automatic: relevant memories are recalled before every reply and appear above as RECALLED "
                     "SEMANTIC MEMORY (and MOST RECENT MEMORIES when the user asks what you talked about); each "
                     "turn is saved after your reply. Earlier chats, voice calls and Telegram share this memory. "
                     "Never call a tool to log, save or recall memories, and never say you will.")
        lines.append("- When nothing relevant was recalled, say plainly that you do not remember it; do not guess.")
    if tool_names is None:
        tool_names = _safe(lambda: _tools_for(ent), [])
    tool_names = list(dict.fromkeys(tool_names or []))
    builtin = [t for t in tool_names if t == "memory_search"]
    others = [t for t in tool_names if t != "memory_search"]
    if builtin:
        lines.append("- Built-in tool memory_search (in-process, same memory store): use it only for a deeper lookup "
                     "the recalled memories missed. mode semantic (meaning), keyword (an exact name, ID, number or "
                     "quoted phrase) or both.")
    if others:
        lines.append("- Tools you may call: " + ", ".join(others) + ". No other tools exist.")
        if _safe(lambda: bool(ent.lazy_tools), False):
            lines.append("- Tool definitions are not preloaded: before calling one of these tools, load its "
                         "inputSchema with the built-in load_tools step (see the tool index).")
    elif not builtin:
        lines.append("- You have no tools in this conversation. Never write <tool_call> or any tool markup.")
    else:
        lines.append("- No other tools exist: no MCP tools are available in this conversation.")
    roles = _safe(lambda: [r for r in _role_keys() if ent.is_set(r)], []) if speaks else []
    if roles:
        lines.append("- Abilities the testbed runs for you when a message needs them (their results appear above): "
                     + ", ".join(roles) + ".")
    ch = current_channel() or getattr(ent, "channel", None) or "terminal"
    if speaks:
        lines.append(f"- Channel: {CHANNELS.get(ch, ch)}. {output_rules(ch)}")
    else:
        lines.append(f"- The user is on: {CHANNELS.get(ch, ch)}. Write plain analysis for the persona; never write "
                     "tool markup unless a tool is listed above.")
    return "\n".join(lines)


def _role_keys():
    from . import roles as R
    return [k for k in getattr(R, "ORDER", None) or list(R.BY_KEY)
            if k not in ("persona", "intent_router", "compactor", "embedding", "reranker")]


def _tools_for(ent):
    from . import selfadmin as SA
    box = SA.active_box()
    if box is not None:
        return [t["name"] for t in box.tools if t.get("name") not in getattr(box, "admin_names", ())]
    names = []
    if getattr(ent, "mcp", None) and ent.mcp.tools:
        names += ent.mcp_exposure()[1]
    names += [t["name"] for t in ent.builtin_tools()]
    return names


def _safe(fn, default):
    try:
        v = fn()
        return default if v is None else v
    except Exception:  # noqa: BLE001 - the block is advisory; a broken part is left out
        return default


# ---------------------------------------------------------------------------
# Lint
# ---------------------------------------------------------------------------
_CALL_RX = re.compile(r"\b([a-z][a-z0-9]*(?:_[a-z0-9]+)+)\s*\(")            # name(  -> a call
_MEM_RX = re.compile(r"\b([a-z][a-z0-9]*_mem)\b", re.IGNORECASE)            # quill_mem, charlie_mem
_VIA_RX = re.compile(r"\b(?:via|using|call|calls|calling|invoke|invoking|through)\s+(?:the\s+)?`?"
                     r"([a-z][a-z0-9]*(?:_[a-z0-9]+)+)`?", re.IGNORECASE)
_GENERIC_TOOLS = re.compile(r"\b(?:chain|trigger|make|issue|plan)\w*\s+(?:the\s+)?(?:required\s+)?"
                            r"(?:MCP\s+)?tool\s+calls?\b", re.IGNORECASE)


def tool_mentions(text):
    """Tool names a prompt tells the model to call."""
    found = []
    for rx in (_CALL_RX, _MEM_RX, _VIA_RX):
        for m in rx.finditer(text or ""):
            n = m.group(1)
            if n not in found:
                found.append(n)
    return found


def lint_prompts(prompts, available, soul=None, role_keys=()):
    """-> [warning]. available: the tool names that exist for the models now."""
    avail = {a.lower() for a in (available or [])}
    skip = {k.lower() for k in role_keys}
    out = []
    items = list((prompts or {}).items()) + ([("soul.md", soul)] if soul else [])
    for role, text in items:
        if not isinstance(text, str):
            continue
        for n in tool_mentions(text):
            if n.lower() in avail or n.lower() in skip:
                continue
            out.append(f"{role} mentions {n}, which is not an available tool")
        if _GENERIC_TOOLS.search(text) and not avail:
            out.append(f"{role} tells the model to make tool calls, but no tools are available to it")
    return out


# ---------------------------------------------------------------------------
# Migration of the user's prompts file
# ---------------------------------------------------------------------------
AUTO_MEMORY_NOTE = ("Memory recall and saving happen automatically (recalled memories appear in your context; each "
                    "turn is saved after your reply), so never call a tool to log or recall memories.")

_FIXES = [
    # "..., and silently log durable facts and session summaries via quill_mem(action='log')"
    (re.compile(r"[,;]?\s*(?:and\s+)?(?:then\s+)?(?:silently\s+|quietly\s+|always\s+)?"
                r"(?:log|save|store|record|persist|write|recall|fetch|retrieve|look up)\b[^.;\n]*?"
                r"\b(?:via|using|with|through|by calling|to)\s+`?[a-z][a-z0-9]*_mem\b(?:\([^)]*\))?`?",
                re.IGNORECASE), ""),
    # "ready for quill_mem(action='log')"
    (re.compile(r"\b(ready|formatted|intended|meant)\s+for\s+`?[a-z][a-z0-9]*_mem\b(?:\([^)]*\))?`?",
                re.IGNORECASE), r"\1 for the testbed's automatic memory store"),
    # "Plan and chain required MCP tool calls before answering"
    (re.compile(r"\bplan and chain (?:the )?(?:required )?(?:MCP )?tool calls before answering", re.IGNORECASE),
     "Plan the steps before answering, and use a tool only if the ENVIRONMENT section lists it"),
    (re.compile(r"\btrigger tool calls when data must be fetched or acted upon", re.IGNORECASE),
     "use a tool only when the ENVIRONMENT section lists one that fits"),
]


def migrate_prompt_text(text, available=()):
    """-> (new_text, changes). Removes the clauses that tell a model to call a
    tool that is not available; everything else stays word for word."""
    if not isinstance(text, str) or not text:
        return text, []
    avail = {a.lower() for a in available or ()}
    t, changes = text, []
    for rx, rep in _FIXES:
        def sub(m, rep=rep):
            names = [n.lower() for n in tool_mentions(m.group(0))]
            if names and all(n in avail for n in names):
                return m.group(0)        # the tool exists: leave it
            changes.append(m.group(0).strip(" ,;"))
            return m.expand(rep) if rep else ""
        t = rx.sub(sub, t)
    # any sentence still naming an unavailable *_mem tool goes
    sentences = re.split(r"(?<=[.!?])\s+", t)
    kept = []
    for s_ in sentences:
        bad = [n for n in _MEM_RX.findall(s_) if n.lower() not in avail]
        if bad:
            changes.append(s_.strip())
            continue
        kept.append(s_)
    t = " ".join(kept) if len(kept) != len(sentences) else t
    t = re.sub(r"\s+([.,;])", r"\1", t)
    t = re.sub(r"[ \t]{2,}", " ", t).strip()
    return t, changes


def migrate_prompts(prompts, available=()):
    """-> (new_prompts, {role: [removed or rewritten text]}). The persona also
    gets the note that memory is automatic when its memory text was removed."""
    out, report = dict(prompts or {}), {}
    for role, text in list(out.items()):
        new, ch = migrate_prompt_text(text, available)
        if ch:
            if role == "persona" and AUTO_MEMORY_NOTE not in new:
                new = (new.rstrip() + (" " if new.rstrip().endswith((".", "!", "?")) else ". ") +
                       AUTO_MEMORY_NOTE).strip()
            out[role] = new
            report[role] = ch
    return out, report


def migrate_prompts_file(path, available=(), log=print):
    """Back the file up, rewrite the stale tool instructions, save. -> report
    ({} when nothing needed changing; the file is then untouched)."""
    from . import config
    data = config.load_json(path, {}) or {}
    if not isinstance(data, dict):
        return {}
    new, report = migrate_prompts(data, available)
    if not report:
        return {}
    backup = f"{path}.bak-{time.strftime('%Y%m%d-%H%M%S')}"
    shutil.copy2(path, backup)
    config.save_json(path, new)
    if log:
        log(f"[prompts] Rewrote tool instructions that named tools that don't exist (backup: {backup}):")
        for role, ch in report.items():
            for c in ch:
                log(f"  {role}: removed \"{c[:110]}\"")
    return {"backup": backup, "changes": report}


def available_tools(ent):
    """Every tool name a model can call right now (MCP after policy + built-in)."""
    names = []
    if getattr(ent, "mcp", None) and getattr(ent.mcp, "tools", None):
        names += ent.mcp_exposure()[1]
    names += [t["name"] for t in _safe(lambda: ent.builtin_tools(), [])]
    return names


def lint_entity(ent):
    from . import roles as R
    return lint_prompts(getattr(ent, "prompts", {}) or {}, available_tools(ent), soul=getattr(ent, "soul", None),
                        role_keys=list(R.BY_KEY) + list(getattr(R, "EXTRA_ROLES", ()) or ()))


def path_exists(p):
    return bool(p) and os.path.exists(p)
